/**
 * build-catalog.ts — bake the comparemypeps (longevity-signal) catalog snapshot
 * into a compact catalog the website ships with.
 *
 * Source of truth for PRODUCTS / PRICES / SALES:
 *   longevity-signal/docs/data/public-catalog-snapshot.json
 *   (generated by that repo's scripts/export-public-catalog.mjs; refreshed by
 *    its twice-daily "nightly-refresh" cron.)
 *
 * Source of truth for VENDOR IDENTITY / AFFILIATE LINKS / ORDER:
 *   src/data/partners.ts  (the client's curated 16, Sunrise removed)
 *
 * We join the two by slug, attach each vendor's products (compound + vial +
 * live price + on-sale state), build an affiliate-tracked URL for every
 * product, and precompute a "Sale of the Week".
 *
 * Run (dev-time only; the output JSON is committed and shipped):
 *   node --experimental-strip-types scripts/build-catalog.ts [snapshotPath]
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { PARTNERS, HOUSE_BRAND, type Partner } from "../src/data/partners.ts";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const SNAPSHOT =
  process.argv[2] ||
  "/home/user/longevity-signal/docs/data/public-catalog-snapshot.json";
const OUT = path.resolve(__dirname, "../src/data/catalog.json");

/** curated slug -> scraper slug, where they differ */
const SLUG_ALIAS: Record<string, string> = {
  "treasure-coast": "treasure-coast-peptide",
};

type Row = Record<string, unknown>;
interface Snapshot {
  generatedAt: string;
  partners: Row[];
  canonicalCompounds: Row[];
  compoundVariants: Row[];
  partnerListings: Row[];
  listingCurrentStates: Row[];
}

function num(v: unknown): number | null {
  if (v === null || v === undefined || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

/** Copy query params from the vendor's tracked affiliate URL onto a product URL. */
function withAffiliateRef(productUrl: string, affiliateUrl: string): string {
  try {
    const pu = new URL(productUrl);
    const au = new URL(affiliateUrl);
    const keys = [...au.searchParams.keys()];
    if (keys.length) {
      for (const [k, v] of au.searchParams) pu.searchParams.set(k, v);
      return pu.toString();
    }
    return productUrl;
  } catch {
    return productUrl || affiliateUrl;
  }
}

export interface CatalogProduct {
  id: number;
  compound: string;
  category: string | null;
  size: string;
  mg: number | null;
  form: string | null;
  price: number | null;
  regularPrice: number | null;
  onSale: boolean;
  discountPct: number | null;
  inStock: boolean;
  currency: string;
  url: string;
  observedAt: string | null;
}

export interface CatalogVendor {
  slug: string;
  name: string;
  website: string;
  affiliateUrl: string;
  code: string | null;
  savings: string;
  savingsPct: number | null;
  order: number;
  region?: string;
  comingSoon?: boolean;
  houseBrand?: boolean;
  productCount: number;
  onSaleCount: number;
  cheapest: number | null;
  products: CatalogProduct[];
}

const snap = JSON.parse(fs.readFileSync(SNAPSHOT, "utf8")) as Snapshot;

const partnerBySlug = new Map<string, Row>();
for (const p of snap.partners) partnerBySlug.set(String(p.slug), p);

const compoundById = new Map<number, Row>();
for (const c of snap.canonicalCompounds) compoundById.set(Number(c.id), c);

const variantById = new Map<number, Row>();
for (const v of snap.compoundVariants) variantById.set(Number(v.id), v);

const stateByListing = new Map<number, Row>();
for (const s of snap.listingCurrentStates) stateByListing.set(Number(s.listingId), s);

const listingsByPartner = new Map<number, Row[]>();
for (const l of snap.partnerListings) {
  const arr = listingsByPartner.get(Number(l.partnerId)) ?? [];
  arr.push(l);
  listingsByPartner.set(Number(l.partnerId), arr);
}

function buildProducts(scraperPartner: Row, affiliateUrl: string): CatalogProduct[] {
  const listings = listingsByPartner.get(Number(scraperPartner.id)) ?? [];
  const products: CatalogProduct[] = [];
  for (const l of listings) {
    if (Number(l.active) === 0) continue;
    const compound = compoundById.get(Number(l.compoundId));
    const variant = variantById.get(Number(l.variantId));
    const state = stateByListing.get(Number(l.id));
    const price = num(state?.listPrice);
    const regular = num(state?.regularPrice);
    const inStock = state ? Number(state.inStock) === 1 : false;
    const onSale = !!(price !== null && regular !== null && regular > price && inStock);
    const discountPct =
      onSale && regular ? Math.round(((regular - price!) / regular) * 100) : null;
    const productUrl =
      (l.affiliateProductUrl as string) || (l.productUrl as string) || affiliateUrl;
    products.push({
      id: Number(l.id),
      compound: String(compound?.displayName ?? l.rawName ?? "Peptide"),
      category: (compound?.category as string) ?? null,
      size: String(variant?.label ?? l.rawSize ?? ""),
      mg: num(variant?.totalMg),
      form: (variant?.form as string) ?? null,
      price,
      regularPrice: regular,
      onSale,
      discountPct,
      inStock,
      currency: String(state?.currency ?? "USD"),
      url: withAffiliateRef(productUrl, affiliateUrl),
      observedAt: (state?.observedAt as string) ?? null,
    });
  }
  // On-sale first, then in-stock, then cheapest.
  products.sort((a, b) => {
    if (a.onSale !== b.onSale) return a.onSale ? -1 : 1;
    if (a.inStock !== b.inStock) return a.inStock ? -1 : 1;
    return (a.price ?? Infinity) - (b.price ?? Infinity);
  });
  return products;
}

const curated: Partner[] = [...PARTNERS, HOUSE_BRAND];

const vendors: CatalogVendor[] = curated.map((p, i) => {
  const scraperSlug = SLUG_ALIAS[p.slug] ?? p.slug;
  const sp = partnerBySlug.get(scraperSlug);
  const products = sp && !p.comingSoon ? buildProducts(sp, p.affiliateUrl || p.websiteUrl) : [];
  const onSaleCount = products.filter((x) => x.onSale).length;
  const inStockPrices = products.filter((x) => x.inStock && x.price !== null).map((x) => x.price!);
  return {
    slug: p.slug,
    name: p.name,
    website: p.websiteUrl,
    affiliateUrl: p.affiliateUrl || p.websiteUrl,
    code: p.code,
    savings: p.savings,
    savingsPct: p.savingsPct,
    order: i,
    region: p.region,
    comingSoon: p.comingSoon,
    houseBrand: p.houseBrand,
    productCount: products.length,
    onSaleCount,
    cheapest: inStockPrices.length ? Math.min(...inStockPrices) : null,
    products,
  };
});

// Sale of the Week: biggest in-stock discount across all vendors.
type SalePick = {
  vendorSlug: string;
  vendorName: string;
  code: string | null;
  product: CatalogProduct;
};
let saleOfWeek: SalePick | null = null;
const topDeals: SalePick[] = [];
for (const v of vendors) {
  for (const prod of v.products) {
    if (!prod.onSale || !prod.inStock || prod.discountPct === null) continue;
    const pick: SalePick = { vendorSlug: v.slug, vendorName: v.name, code: v.code, product: prod };
    topDeals.push(pick);
  }
}
topDeals.sort(
  (a, b) =>
    (b.product.discountPct ?? 0) - (a.product.discountPct ?? 0) ||
    (b.product.regularPrice ?? 0) - (b.product.price ?? 0) -
      ((a.product.regularPrice ?? 0) - (a.product.price ?? 0)),
);
saleOfWeek = topDeals[0] ?? null;

const catalog = {
  generatedAt: snap.generatedAt,
  bakedAt: new Date().toISOString(),
  vendorCount: vendors.length,
  productCount: vendors.reduce((n, v) => n + v.productCount, 0),
  saleOfWeek,
  topDeals: topDeals.slice(0, 8),
  vendors,
};

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, `${JSON.stringify(catalog, null, 2)}\n`, "utf8");

const withProducts = vendors.filter((v) => v.productCount > 0).length;
console.log(
  `Wrote ${path.relative(process.cwd(), OUT)} — ${vendors.length} vendors ` +
    `(${withProducts} with products), ${catalog.productCount} products, ` +
    `${topDeals.length} on sale. Sale of week: ${
      saleOfWeek
        ? `${saleOfWeek.vendorName} ${saleOfWeek.product.compound} ${saleOfWeek.product.size} (-${saleOfWeek.product.discountPct}%)`
        : "none"
    }`,
);
